<?php use App\Core\Helpers as H;$canManage=H::canAdmin('promotions.manage');?><h1>Promotions</h1><h2>Promo Pricing</h2><p>Placement and duration are fixed. New prices apply only to future purchases.</p><div class="promo-pricing"><?php foreach($packages as $p):?><article class="card"><strong><?=H::e(ucwords(str_replace('_',' ',$p['placement'])))?> — <?=$p['duration_value'].' '.$p['duration_unit'].($p['duration_value']>1?'s':'')?></strong><p><?=H::money($p['price_cents']/100)?></p><?php if($canManage):?><form method="post"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="action" value="update_price"><input type="hidden" name="id" value="<?=$p['id']?>"><label>Price $ <input type="number" name="price" min="0.01" step="0.01" value="<?=number_format($p['price_cents']/100,2,'.','')?>"></label><button>Save</button></form><?php endif;?></article><?php endforeach;?></div>
<h2>Campaigns</h2><div class="promo-table"><table><tr><th>Seller / target</th><th>Placement</th><th>Snapshot</th><th>Payment / status</th><th>Schedule</th><th>Stats</th><th>Actions</th></tr><?php foreach($campaigns as $a):?><tr><td><?=H::e($a['display_name'])?><br><?=H::e($a['target_type']==='shop'?'Shop':($a['product_title']??'Unavailable product'))?></td><td><?=H::e($a['placement'])?></td><td><?=$a['duration_value'].' '.$a['duration_unit']?><br><?=H::money($a['price_cents']/100)?></td><td><?=H::e($a['payment_status'])?><br><?=H::e($a['status'])?></td><td><?=H::e($a['starts_at']??'—')?><br><?=H::e($a['ends_at']??'—')?></td><td>Impressions: <?=(int)$a['impressions']?><br>Clicks: <?=(int)$a['clicks']?></td><td><?php if($canManage):$actions=$a['status']==='active'?['pause','remove']:($a['status']==='paused'?['resume','remove']:(!empty($a['emergency_removable'])?['remove']:[]));foreach($actions as $action):?><form method="post"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><input type="hidden" name="id" value="<?=$a['id']?>"><button name="action" value="<?=$action?>"><?=ucfirst($action)?></button></form><?php endforeach;endif;?></td></tr><?php endforeach;?></table></div>
